    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    nonbg = Counter(v for row in grid for v in row if v != bg)
    frame = nonbg.most_common(1)[0][0]
    fills = set(nonbg) - {frame}

    # Find each interior fragment separately. This also separates fragments
    # whose outer borders happen to touch in the input.
    seen = set()
    chunks = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in fills or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                (ny, nx) not in seen and grid[ny][nx] == color):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            chunks.append((color, cells))

    # Assign border pixels to their nearest interior fragment.
    borders = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == frame]
    assigned = [[] for _ in chunks]
    for y, x in borders:
        best = min(range(len(chunks)), key=lambda i:
                   min(abs(y - a) + abs(x - b) for a, b in chunks[i][1]))
        assigned[best].append((y, x))

    groups = {}
    for i, (color, cells) in enumerate(chunks):
        coords = [(y, x, color) for y, x in cells]
        coords += [(y, x, frame) for y, x in assigned[i]]
        ys = [z[0] for z in coords]
        xs = [z[1] for z in coords]
        y0, x0 = min(ys), min(xs)
        a = [[bg] * (max(xs) - x0 + 1) for _ in range(max(ys) - y0 + 1)]
        for y, x, v in coords:
            a[y - y0][x - x0] = v
        p = {'a': a, 'h': len(a), 'w': len(a[0]), 'fill': color,
             'source_y': y0, 'source_x': x0}
        groups.setdefault(color, []).append(p)

    def full_row(p, r):
        return all(v == frame for v in p['a'][r])

    def full_col(p, c):
        return all(p['a'][r][c] == frame for r in range(p['h']))

    def paste(can, p, y, x):
        for r in range(p['h']):
            for c in range(p['w']):
                if p['a'][r][c] != bg and 0 <= y+r < len(can) and 0 <= x+c < len(can[0]):
                    can[y+r][x+c] = p['a'][r][c]

    rendered = []
    for color in sorted(groups):
        ps = groups[color]
        if len(ps) == 2:
            left, right = sorted(ps, key=lambda p: p['w'], reverse=True)
            ph = min(left['h'], right['h'])
            pw = left['w'] + right['w']
            can = [[bg] * pw for _ in range(ph)]
            paste(can, left, 0, 0)
            paste(can, right, ph-right['h'], left['w'])
        else:
            lefts = [p for p in ps if full_col(p, 0)]
            rights = [p for p in ps if full_col(p, p['w']-1) and p not in lefts]

            def order(pair):
                if len(pair) == 1:
                    return pair[0], None
                a, b = pair
                if full_row(a, a['h']-1) != full_row(b, b['h']-1):
                    bottom = a if full_row(a, a['h']-1) else b
                else:
                    bottom = b if full_row(a, 0) else a
                return (b if bottom is a else a), bottom

            tl, bl = order(lefts)
            tr, br = order(rights)
            lw = max(p['w'] for p in lefts)
            rw = max(p['w'] for p in rights)
            th = max(tl['h'], tr['h'])
            bh = max(bl['h'], br['h'])
            can = [[bg] * (lw+rw) for _ in range(th+bh-1)]
            paste(can, tl, 0, 0)
            paste(can, tr, 0, lw)
            paste(can, bl, th-1, 0)
            paste(can, br, th-1, lw)
        rendered.append(can)

    out = [[bg] * w for _ in range(h)]
